require __DIR__.'/bootstrap.php';require_auth();if(!can('sales.create')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$productIds=$_POST['product_id']??[];$quantities=$_POST['quantity']??[];$discounts=$_POST['line_discount']??[];if(!$productIds){flash('danger','Add at least one product.');redirect('sale.php');}$db->beginTransaction();try{$saleType=$_POST['sale_type']==='wholesale'?'wholesale':'retail';$paymentType=$_POST['payment_type']==='credit'?'credit':'cash';$customerId=(int)($_POST['customer_id']??0)?:null;if($paymentType==='credit'&&!$customerId)throw new RuntimeException('A credit customer is required.');$lines=[];$subtotal=0;$totalCost=0;foreach($productIds as $i=>$pid){$qty=(float)($quantities[$i]??0);if($qty<=0)continue;$st=$db->prepare('SELECT * FROM products WHERE id=? AND status="active" FOR UPDATE');$st->execute([(int)$pid]);$p=$st->fetch();if(!$p)throw new RuntimeException('A selected product is unavailable.');if($qty>(float)$p['current_stock']&&user()['role_code']!=='main_admin')throw new RuntimeException($p['name'].' has insufficient stock.');$price=(float)$p[$saleType.'_price'];$discount=max(0,(float)($discounts[$i]??0));$lineTotal=$qty*$price-$discount;$cost=$qty*(float)$p['avg_cost'];$lines[]=[$p,$qty,$price,$discount,$lineTotal,$lineTotal-$cost];$subtotal+=$qty*$price;$totalCost+=$cost;}if(!$lines)throw new RuntimeException('Add a valid quantity.');$invoiceDiscount=max(0,(float)($_POST['discount']??0));$total=max(0,$subtotal-$invoiceDiscount);$paid=max(0,min($total,(float)($_POST['paid_amount']??0)));$balance=$total-$paid;$status=$balance<=0?'paid':($paid>0?'partially_paid':'unpaid');$seq=(int)$db->query("SELECT COALESCE(MAX(id),0)+1 FROM sales")->fetchColumn();$saleNo='SALE-'.date('Y').'-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT);$stmt=$db->prepare('INSERT INTO sales(sale_no,customer_id,sale_date,sale_type,payment_type,subtotal,discount,total,paid_amount,balance,due_date,status,notes,created_by) VALUES(?,?,NOW(),?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$saleNo,$customerId,$saleType,$paymentType,$subtotal,$invoiceDiscount,$total,$paid,$balance,$_POST['due_date']?:null,$status,trim($_POST['notes']??''),user()['id']]);$saleId=(int)$db->lastInsertId();$itemStmt=$db->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,historical_unit_cost,discount,line_total,gross_profit) VALUES(?,?,?,?,?,?,?,?)');$stockStmt=$db->prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?');$moveStmt=$db->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,unit_cost,running_quantity,reference_type,reference_id,created_by) VALUES(?,?,?,?,?,?,?,?)');foreach($lines as [$p,$qty,$price,$disc,$lineTotal,$profit]){$allocated=$subtotal>0?$invoiceDiscount*(($qty*$price)/$subtotal):0;$finalLine=$lineTotal-$allocated;$profit=$finalLine-$qty*(float)$p['avg_cost'];$itemStmt->execute([$saleId,$p['id'],$qty,$price,$p['avg_cost'],$disc+$allocated,$finalLine,$profit]);$stockStmt->execute([$qty,$p['id']]);$moveStmt->execute([$p['id'],$paymentType.'_sale',-$qty,$p['avg_cost'],(float)$p['current_stock']-$qty,'sale',$saleId,user()['id']]);}if($paid>0){$db->prepare('INSERT INTO sale_payments(sale_id,method,amount,reference_no) VALUES(?,?,?,?)')->execute([$saleId,$_POST['payment_method'],$paid,trim($_POST['reference_no']??'')]);}if($customerId){$db->prepare('UPDATE customers SET outstanding=outstanding+?,total_sales=total_sales+?,total_payments=total_payments+?,last_purchase_at=NOW() WHERE id=?')->execute([$balance,$total,$paid,$customerId]);}audit($db,'create','sale',$saleId,null,['sale_no'=>$saleNo,'total'=>$total,'balance'=>$balance]);$db->commit();flash('success',"Sale $saleNo saved successfully.");redirect('sale.php?completed='.urlencode($saleNo));}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('sale.php');}}
$products=$db->query('SELECT id,item_code,name,current_stock,retail_price,wholesale_price FROM products WHERE status="active" AND current_stock>0 ORDER BY name')->fetchAll();$customers=$db->query('SELECT id,customer_code,name,customer_type,credit_enabled FROM customers WHERE status="active" ORDER BY name')->fetchAll();page_start('New sale','sale.php');?>
<form method="post" id="sale-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="sale-layout"><section><article class="panel"><div class="panel-head"><div><span class="eyebrow">Sale details</span><h3>Customer & pricing</h3></div></div><div class="form-grid"><label>Customer<select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['customer_code'].' · '.$c['name'])?></option><?php endforeach;?></select></label><label>Sale type<select name="sale_type" id="sale-type"><option value="retail">Retail price</option><option value="wholesale">Wholesale price</option></select></label><label>Payment type<select name="payment_type" id="payment-type"><option value="cash">Cash sale</option><option value="credit">Credit sale</option></select></label><label>Due date<input type="date" name="due_date"></label></div></article><article class="panel table-panel sale-lines" style="margin-top:20px"><div class="panel-head"><div><span class="eyebrow">Invoice items</span><h3>Products</h3></div><button type="button" class="btn secondary" id="add-line">＋ Add line</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Qty</th><th>Discount</th><th class="right">Line total</th><th></th></tr></thead><tbody id="lines"></tbody></table></div></article></section><aside class="panel sale-summary"><div class="panel-head"><div><span class="eyebrow">Payment</span><h3>Sale summary</h3></div></div><div class="summary-row"><span>Subtotal</span><b id="subtotal">Rs. 0.00</b></div><label>Invoice discount<input type="number" min="0" step=".01" name="discount" id="discount" value="0"></label><div class="summary-row total"><span>Total</span><strong id="grand-total">Rs. 0.00</strong></div><label>Paid amount<input type="number" min="0" step=".01" name="paid_amount" id="paid" value="0"></label><div class="summary-row"><span>Balance</span><b id="balance">Rs. 0.00</b></div><label>Payment method<select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="other">Other / mixed</option></select></label><label>Reference<input name="reference_no"></label><label>Notes<textarea name="notes" rows="3"></textarea></label><button class="btn primary wide" style="margin-top:16px">Save sale</button></aside></div></form>
<template id="line-template"><tr><td><select name="product_id[]" class="product" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-stock="<?=$p['current_stock']?>" data-retail="<?=$p['retail_price']?>" data-wholesale="<?=$p['wholesale_price']?>"><?=e($p['item_code'].' · '.$p['name'])?></option><?php endforeach;?></select></td><td class="stock">—</td><td><input class="qty" type="number" name="quantity[]" min=".001" step=".001" value="1" required></td><td><input class="line-discount" type="number" name="line_discount[]" min="0" step=".01" value="0"></td><td class="right line-total">Rs. 0.00</td><td><button type="button" class="icon-button remove">×</button></td></tr></template><script>const lines=document.querySelector('#lines'),tpl=document.querySelector('#line-template'),fmt=n=>'Rs. '+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let sub=0;lines.querySelectorAll('tr').forEach(r=>{const o=r.querySelector('.product').selectedOptions[0],type=document.querySelector('#sale-type').value,p=+(o?.dataset[type]||0),q=+r.querySelector('.qty').value||0,d=+r.querySelector('.line-discount').value||0,t=Math.max(0,p*q-d);r.querySelector('.stock').textContent=o?.dataset.stock||'—';r.querySelector('.line-total').textContent=fmt(t);sub+=t});const total=Math.max(0,sub-(+document.querySelector('#discount').value||0)),bal=Math.max(0,total-(+document.querySelector('#paid').value||0));document.querySelector('#subtotal').textContent=fmt(sub);document.querySelector('#grand-total').textContent=fmt(total);document.querySelector('#balance').textContent=fmt(bal)}function add(){lines.append(tpl.content.cloneNode(true));calc()}document.querySelector('#add-line').onclick=add;document.querySelector('#sale-type').onchange=calc;document.querySelector('#discount').oninput=calc;document.querySelector('#paid').oninput=calc;lines.addEventListener('input',calc);lines.addEventListener('change',calc);lines.addEventListener('click',e=>{if(e.target.classList.contains('remove')){e.target.closest('tr').remove();calc()}});add();</script><?php page_end();

